(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fo"] = {"ui":{"skip":"Far til innihaldið","back":"← Aftur til AI-gile","lang.button":"Mál: {name}","lang.dialog":"Vel eitt mál","lang.search":"Leita eftir máli","lang.none":"Einki mál hóvar","lang.notYet":"{name} er ikki umsett enn","theme.aria":"Skift millum ljósan og myrkan hátt","theme.toLight":"Skift til ljósan hátt","theme.toDark":"Skift til myrkan hátt","words.underline":"Strika undir hesi orðini á síðuni","words.underlineHelp":"Halt músina yvir ella trýst á eitt prikkað orð fyri at síggja, hvat tað merkir.","index.title":"AI-gile: títt AI-menningarlið, á einum borði","index.description":"AI-gile er eitt kanban-borð til AI-kodulið. Tey arbeiða meðan tú sovir; tú fært ein stuttan bunka við tilfarið at taka avgerð um, royna og góðkenna.","hero.logoAlt":"AI-gile borðtekn","hero.h1.html":"Títt AI-menningarlið, á einum&nbsp;borði.","hero.alpha":"🐣 Lukkað pre-alfa","hero.alphaTitle":"Tíðliga og ikki liðugt: takk fyri at royna!","hero.lede":"Tey byggja meðan tú sovir. Tú vaknar til ein stuttan bunka: nøkur spurningar, nøkur at royna, ein ella tveir purpurdiamantir. Klikk, góðkent, aftur til kaffibollan.","dl.windows":"Windows-app","dl.browser":"Brúka í kagarinum","dl.soon":"Kemur skjótt","dl.notify":"🔔 Boða mær frá, tá tað letur upp","dl.notifySmall":"Alfa ella beta","hero.secondary":"Agile, men liðið hevur ongantíð brúk fyri standandi-fundar-kaffi. (Tey hava standandi fund kortini.)","pitch.h2":"AI-gile í so nógvum orðum, sum tú vilt","pitch.lede":"Vel eina longd, frá einum orði upp í 144. Hvør longd er sín egni frágreiðing, skrivað til tann stødd. Drag rennuna ella brúka pílarnar.","pitch.rangeLabel":"Longd í orðum","pitch.dice":"🎲 ein onnur útgáva","pitch.words.one":"{n} orð","pitch.words.other":"{n} orð","pitch.letters.one":"{n} bókstavur","pitch.letters.other":"{n} bókstavir","pitch.chars.one":"{n} tekin","pitch.chars.other":"{n} tekin","count.line.html.one":"{n} kort á borðinum júst nú","count.line.html.other":"{n} kort á borðinum júst nú","features.aria":"Hvat tað ger","f.pile.h":"Ein bunki til tín","f.pile.html":"<b>Fyri teg</b> inniheldur alt, sum bíðar eftir tær, í øllum verkætlanum: spurningar, tilfar at royna, uppgávur, sum bara ein maður kann gera. Tín bíðirøð sigur, hvat er næst og hvussu leingi tað tekur.","f.sleep.h":"Lið, sum arbeiða meðan tú sovir","f.sleep.p":"Hvør verkætlan hevur ein leiðara og eitt lið av AI-agentum. Skriva eina viðmerking á eitt kort, og liðið vaknar, ger arbeiðið og gevur tær tað aftur við stigum, sum eisini ein móður maður kann fylgja.","f.tester.h":"Ein AI-royndari kannar fyrst","f.tester.p":"Áðrenn nakað kemur til tín, fylgir ein royndari stigunum í einum avriti av appini og vísir, hvat hann sá, við skíggjamynd. Blaða tú gjøgnum tey, sum eru greidd, og góðkenn við einum klikki.","f.proof.h":"Prógv, ikki lyfti","f.proof.p":"Hvør yvirlatan vísir, hvat broytt er: fílurnar, diff-ið, skíggjamyndirnar. Tú sleppur undan at lata hvørt app upp fyri at sæa, um tað er liðugt.","f.chat.h":"Práta við leiðararnar hjá tær","f.chat.p":"Ein Discord-líknandi rekki: eitt tekn fyri hvørja verkætlan, purpurdiamantir fyri tað, sum hevur brúk fyri tær. Send leiðaranum eitt hugskot; hann ger kort og eina ætlan burturúr, við einum ✅ Go-knappi.","f.tidy.h":"Heldur seg sjálvt rættiliga","f.tidy.p":"Kort, sum hanga saman, renna saman, ruglaðir heitir verða rættaðir, og ein tokenkanning heldur kodu lættari. Færri ting at skifta millum, minni at hugsa um.","f.private.h":"Títt, á tíni teldu","f.private.li1":"Borðið koyrir á tínari egnu maskinu og svarar bara tær.","f.private.li2":"Privatar boð millum fólk eru enda-til-enda krypterað.","f.private.li3":"Eingin konta, ongir fylgjarar, ongar cookies.","f.lang.h":"Á tínum máli","f.lang.p":"Meiri enn 120 mál, frá hollendskum, valisiskum og japanskum til sjóræningamál, Yoda og klingonskt, við skjótum skifti aftur til enskt fyri orðini hjá menningarfólki.","tl.aria":"Tíðarlinja frá fyrsta samrøðu til vegakortið","tl.h2":"Frá fyrstu práti til tað, sum er næst","tl.lede":"Veruligar dagar og tíðir, í tínum egna tíðarsvæði. Aftaná í dag er tað ætlanin, uttan lovaðar dagar.","tl.today":"Í dag","tl.planned":"ætlað","tl.cards.one":"{n} kort","tl.cards.other":"{n} kort","join.h2":"Vertu við","join.lede":"AI-gile verður bygt av einum lítlum manni og nógvum tolnum agentum. Tað er privat enn, í lukkaðari alfu saman við vinum. Vilt tú royna, tá tað letur upp?","join.btn":"Boða frá áhuga","join.small":"Vit senda tær teldupost, einki annað","footer.tag":"AI-gile. Ongir fylgjarar, ongar cookies, einki standandi-fundar-kaffi.","footer.licence":"Fyritøkuloyvi","footer.status":"Støða","footer.privacy":"Hvat vit goyma","form.sending":"Sendi…","form.failed":"Tað riggaði ikki: royn aftur seinni.","form.offline":"Fekk ikki samband við AI-gile: royn aftur seinni.","form.keep":"Vit brúka hetta bert til at svara tær, síðan strika vit tað. Ongir fylgjarar, ongar cookies.","form.keepLink":"Hvat vit goyma","interest.title":"AI-gile: boða mær frá, tá alfan letur upp","interest.description":"Skriva tín teldupost fyri at frætta, tá lukkaða alfan ella betan hjá AI-gile letur upp.","interest.h1":"🔔 Boða mær frá, tá tað letur upp","interest.lede":"AI-gile er í lukkaðari pre-alfu. Skriva tín teldupost, og vit skriva tær eina ferð, tá pláss er til tín.","interest.email":"Tín teldupostur","interest.which":"Hvør royndin?","interest.alpha":"Lukkað alfa: tíðliga, ruggað, nógvar broytingar","interest.beta":"Beta: støðugari, seinni","interest.both":"Annaðhvørt, hvat so fyrst letur upp","interest.submit":"Set meg á listan","interest.thanks":"Takk! Tú ert á listanum.","licence.title":"AI-gile: fyritøkuloyvi","licence.description":"Brúkar tú AI-gile í tíni fyritøku? Søk um eitt ókeypis fyritøkuloyvi.","licence.h1":"📜 Fyritøkuloyvi","licence.lede":"Brúkar tú AI-gile á arbeiðsplássinum? Sig okkum, hvør tú ert og hvat tú gert. Um tað ger gott, er loyvið ókeypis.","licence.company":"Fyritøka","licence.website":"Heimasíða","licence.what":"Hvat tú gert","licence.how":"Hvussu tað hjálpir heiminum","licence.email":"Teldupostur","licence.submit":"Søk","licence.thanks":"Takk! Vit svara við teldupósti.","status.title":"AI-gile støða","status.h1":"AI-gile støða","status.quiet":"Alt er kvirt","status.intro":"Riggar AI-gile júst nú? Henda síðan kannar heimasíðuna, deiling av talvum, samtalur og niðurtøkuna hvørjar 5 minuttir.","status.up":"Riggar (svaraði eftir {ms} ms)","status.slow":"Svaraði ikki seinastu kanningini, royni aftur","status.down":"Úr gongd: svaraði ikki seinastu tveimum kanningunum","status.svc.web":"Heimasíða","status.svc.web.offers":"Henda síðan: hvat AI-gile er, og áhugaformularin","status.svc.boards":"Deiling av talvum","status.svc.boards.offers":"Almennar talvur, boð millum vinir og innbjóðingar","status.svc.calls":"Samtalur","status.svc.calls.offers":"Rødd, video og skermdeiling í AI-gile","status.svc.download":"Niðurtøka","status.svc.download.offers":"Windows-innleggjarin og innbjóðingarleinkjur","status.checking":"Kanni…","status.offline":"Fái ikki samband við støðutænastuna júst nú (royni aftur)","status.updated":"dagført {ago}","status.justNow":"júst nú","status.min":"{n} min síðani","status.hours":"{n} t síðani","status.days":"{n} d síðani","privacy.title":"AI-gile: hvat vit goyma","privacy.h1":"Hvat vit goyma","privacy.lede":"Stutt sagt: bert tað, tú sendir okkum, og ikki leingi.","privacy.only":"Bert tað, tú sendir okkum: tað, tú skrivar í eitt formular, so sum teldupostin hjá tær. Einki annað um teg.","privacy.sealed":"Tað verður innsiglað, so ambætarin hjá okkum ikki kann lesa tað: í kaganum hjá tær, áðrenn tað fer avstað (á einum eldri kaga, tá ið tað kemur fram). Bert okkara egna talva kann lata tað upp.","privacy.server":"Tað verður strikað av ambætaranum, so skjótt sum tað kemur fram á talvuna hjá okkum. Alt, ið enn liggur har eftir 30 dagar, verður strikað líkavæl.","privacy.board":"Vit goyma tað á talvuni hjá okkum bert, til vit hava svarað tær, síðan strika vit tað har eisini.","privacy.none":"Ongir fylgjarar, ongar cookies, eingin greining.","privacy.local":"Málið hjá tær og valið millum ljóst og myrkt verða verandi í tínum egna kaga. Tey verða ongantíð send til okkara.","privacy.ask":"Vilt tú hava tað burtur fyrr? Svara teldupostinum frá okkum og sig frá.","live.h2":"Sær tað verða bygt, beinleiðis","live.caption":"Hvert kort er fjalt: tú sært skapið á arbeiðinum, ikki orðini.","live.watching.one":"beinleiðis: {n} hyggja","live.watching.other":"beinleiðis: {n} hyggja","live.last.now":"Seinasta kort flutt júst nú","live.last.min.one":"Seinasta kort flutt fyri {n} min síðani","live.last.min.other":"Seinasta kort flutt fyri {n} min síðani","live.last.hour.one":"Seinasta kort flutt fyri {n} tíma síðani","live.last.hour.other":"Seinasta kort flutt fyri {n} tímum síðani","live.last.day.one":"Seinasta kort flutt fyri {n} degi síðani","live.last.day.other":"Seinasta kort flutt fyri {n} døgum síðani","live.offline":"Beinleiðis talvan tekur sær eina løtu at kvíla. Kom aftur skjótt.","live.cols":"Backlog|At gera|Í gerð|Toymið kannar|Fyri teg at testa|Fyri toymið|Liðugt"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotar.","Avgreitt."]},{"n":2,"texts":["Robotar arbeiða.","Agentar, skipaðir.","Hugskot, bygd."]},{"n":3,"texts":["Kanban fyri robotar.","Hugskot verða eyðkenni.","Ókeypis agent-kanban."]},{"n":5,"texts":["Kanban-borð rikið av agentum.","Tú skrivar, agentar byggja.","Ókeypis, lokalt, roynt, eitt sindur tilkomið."]},{"n":8,"texts":["Eitt ókeypis kanban-borð, har AI-agentar arbeiða.","Skriva eitt hugskot. Agentar byggja. Tú góðkennir.","Agile fyri ein mann og nógvar tolnar robotar."]},{"n":13,"texts":["Eitt kanban-borð á tíni teldu, har AI-agentar taka kortini og gera arbeiðið.","Skriva eitt hugskot. Eitt lið av agentum bygger tað. Ein royndari kannar tað.","Ókeypis, eingin konta, ongir fylgjarar: eitt borð, nakrir robotar, og tú ræður."]},{"n":21,"texts":["AI-gile er eitt kanban-borð at arbeiða saman við AI-kodaagentum. Tey taka kortini; tú roynir tey og góðkennir tey.","Hvør verkætlan fær ein leiðara og eitt lið av AI-agentum. Skriva eina viðmerking á hvørt kort, og liðið fer til verka.","Eitt ókeypis, persónligt uppgávuborð, sum koyrir á tíni egnu teldu. Arbeiðararnir eru robotar. Tann, sum sigur ja, ert tú."]},{"n":34,"texts":["Tú leggur hugskot á eitt borð. Eitt lið av AI-agentum ger tey til virkandi eyðkenni, roynir tey og gevur tær tey aftur við stigum at royna. Einki telst sum liðugt, fyrr enn tú sigur tað.","AI-gile er eitt heimagjørt kanban-borð, sum Rich bygdi við nógvari hjálp frá teimum agentum, sum tað nú stýrir. Tað er ókeypis, koyrir á tíni teldu og verður deilt við vinir, ikki selt.","Hugsa tær eitt vanligt kanban-borð, við súlum frá Backlog til Liðugt, nema at kortini verða tikin av AI-agentum. Tey boða frá framgongd, spyrja, tá tey sita fast, og bíða altíð eftir tínari góðkenning."]},{"n":55,"texts":["AI-gile er eitt kanban-borð, har liðið er gjørt av AI-agentum. Hvør verkætlan hevur ein leiðara, sum ætlar arbeiðið, og hjálparar, sum byggja tað. Tá eitt eyðkenni er klárt, roynir ein AI-royndari tað og tekur eina skíggjamynd, síðani kemur tað í tín bunka. Góðkenn tað, ella skriva eina viðmerking, og tey gera tað umaftur.","Tað byrjaði sum háttur hjá einum manni at fylgja við í nógvum AI-kodusessiónum í senn, og vaks til eitt veruligt borð. Tað koyrir á tíni maskinu, krevur onga kontu og hevur ongar fylgjarar. Tað er ókeypis fyri vinir og forvitin. Tað er eisini ikki liðugt, so ríkna við rúgvum kantum og einstaka undran.","Her er sanna útgávan. Tú mást enn hava hugskotini, og tú mást enn kanna úrslitini. Tað, sum AI-gile ger, er alt hitt ímillum: tað heldur kortunum í røð, vekur røttan agent, tá tú skrivar viðmerking, vísir júst hvat broytt er, og leggur alt í ein stuttan bunka til tín."]},{"n":89,"texts":["AI-gile er eitt ókeypis kanban-borð, sum tú letur koyra á tíni egnu teldu. Í staðin fyri fólk hevur hvør verkætlan eitt lið av AI-agentum: ein leiðara, sum ger hugskotini hjá tær til kort og eina ætlan, og hjálparar, sum taka kortini í raðfylgju eftir týdningi. Tá okkurt er bygt, fylgir ein AI-royndari royndarstigunum og vísir tær, hvat hann sá. Síðani bíðar tað í einum bunka, sum eitur Fyri teg. Tú góðkennir tað, ella tú skrivar eina viðmerking, og liðið roynir enn eina ferð. Einki kemur nakrantíð til Liðugt uttan teg.","Nøkur eyðkenni, sum tú kanska ikki væntar. Ein náttarvakt heldur súlini At gera fullari, meðan tú sovir, og velur kort, sum ikki hava brúk fyri svari frá tær. Ein tokentalari vísir, hvussu nógv agentarnir hava brúkt í dag og hesa vikuna, og Eingin token-hátturin sigur teimum at steðga at brúka. Tú kanst senda vinum boð, og privat boð eru enda-til-enda krypterað. Borðið tosar umleið 120 mál, millum annað hollendskt, flamskt, sjóræningamál og klingonskt. Einki av hesum kostar ein oyra, og ongin roynir at selja tær tað.","AI-gile er eitt lítið, persónligt tiltak, ikki ein fyritøka. Rich vildi taka sær av fleiri AI-kodaverkætlanum uttan at lata hvørt app upp fyri at kanna tær, so hann og agentarnir bygdu eitt borð til tað, og brúktu síðani borðið til at byggja restina av sær sjálvum. Tað er í lukkaðari pre-alfu, sum merkir, at tað riggar, mestsum, fyri ein bólk av vinum. Her er eingin prísasíða, einki fregnbræv og ongin vøkstrarætlan. Um tað ljóðar nyttigt, kanst tú biðja um at royna tað, tá tað letur eitt sindur meiri upp."]},{"n":144,"texts":["AI-gile er eitt kanban-borð fyri ein mann og nógvar AI-agentar. Tað koyrir á tíni egnu teldu og er heilt ókeypis. Tú leggur verkætlanir afturat, og hvør verkætlan fær ein leiðara og eitt lítið lið. Tú prátar við leiðaran, eitt sindur sum á Discord, og lýsir eitt hugskot; leiðarin ger kort og eina ætlan burturúr og bíðar síðani eftir, at tú trýstir á Go. Liðið arbeiðir seg gjøgnum kortini í raðfylgju eftir týdningi, við einari einfaldari boðraðlinju gjørdari til málmodellir. Áðrenn nakað kemur aftur til tín, fylgir ein AI-royndari stigunum í einum avriti av appini og leggur eina skíggjamynd við. Liðugt arbeiði kemur í tín bunka við broyttum fílum og diff-inum. Tú góðkennir tað, ella tú letur eina viðmerking eftir, og liðið vaknar og roynir aftur. Bara tú kanst flyta eitt kort til Liðugt.","Ein dagur við AI-gile, umleið. Um kvøldið letur tú nøkur viðmerkingar eftir: hesin knappurin er á skeivum stað, hin listin eigur at vera raðfest, kundi tað eisini fingið myrkan hátt. Tú fert í song. Agentarnir lesa viðmerkingarnar, gera broytingarnar, royna tær og geva tær aftur til tín. Um At gera tæmist, fyllir náttarvaktin tað úr backlog við kortum, sum ikki hava brúk fyri svari frá tær. Um morgunin er ein stuttur bunki: nøkur spurningar og nøkur ting at royna, hvørt við stigum, sum ein søvnugur maður kann fylgja, og skíggjamynd av, at tað riggar. Tú klikkar teg gjøgnum, góðkennir tey góðu og sendir restina aftur. Ein tokentalari vísir, hvat alt hetta brúkti, og Eingin token-hátturin er til tær magru vikurnar. So etur tú morgunmat, sum agentarnir ikki kunnu hjálpa við enn.","Fyrst, hvat AI-gile ikki er. Tað er ikki ein startup, tað er ikki til sølu, og ongin savnar tínar dátur. Tað er eitt ókeypis borð, sum koyrir á tíni teldu, uttan kontur, uttan fylgjarar og uttan cookies. Hvat tað er: ein rættilig støð at sæa allar AI-kodaverkætlanirnar í senn, við einum liði av agentum, sum gera kortini, og tær, sum taka avgerðirnar. Tað rennur kort saman, sum hanga saman, rættar ruglaðar heitir, og hevur eyga við, um kodan verður verandi lætt. Tað tosar umleið 120 mál, frá hollendskum og flamskum til sjóræningamál og klingonskt. Vinir kunnu senda hvønn øðrum boð, privat og krypterað. Tað varð bygt av Rich og nógvum tolnum agentum, mestsum við at brúka seg sjálvt. Tað er í lukkaðari pre-alfu, so tað er ruggað sums staðni. Um tað ljóðar stuttligt, bið vælsiðað, og kanska sleppur tú tíðliga inn."]}],"quips":{"1":"Eitt orð. Djarvt. Kanska ov djarvt.","3":"Trý orð. Longu ærligari enn flestu vøruvevir.","8":"Átta orð. Enn styttri enn ein standandi fundur.","21":"Longdirnar eru annars story points. Sjálvsagt eru tær tað.","55":"Fimmtiofimm orð. Tvey kort vórðu liðug, meðan tú las hetta.","144":"Hetta er tann langa. Ongin 233 er til. Agentarnir eru farnir í song."}},"timeline":{"first-idea.name":"Fyrsta hugskotið","first-idea.line":"Fyrsta samrøða av øllum, áðrenn nøkur koda var til.","first-board.name":"Fyrsta borð","first-board.line":"Eitt borð, sum fylgir sínum egna bygnaði: kort, súlur, drag og slepp, verkætlanir.","team-roles.name":"Lið og leiklutir","team-roles.line":"Agentprofilir, liðsmynstur, rúm og hvør ger hvat.","install.name":"Uppsetan og útgávur","install.line":"Ein zip, sum ein vinur kann seta upp, sjálvdagføring, rásir og afturrulling.","usage-saver.name":"Nýtslusparing","usage-saver.line":"Máta hvat koyringar kosta, halda kodu lættari, spara markið hjá tær.","friends.name":"Vinir og deiling","friends.line":"Privatar boð, ruglað relay, innbjóðingar, leiklutir og deild verkætlanir.","languages.name":"Mál","languages.line":"Hvør skíggjatekstur í einari málfílu, við hollendskum og flamskum fyrst.","ai-tester.name":"AI-royndari","ai-tester.line":"Ein royndari kannar hvørja yvirlatan fyrst og vísir, hvat hann sá.","website.name":"Heimasíðan","website.line":"aigile.lol, teaserin og henda tíðarlinjan.","streaming.name":"Prát og streymur","streaming.line":"Discord, Twitch, OBS, streymarahættur, GIF og emojir.","no-ai.name":"Útgáva uttan AI","no-ai.line":"Eitt borð til tey, sum koda uttan AI, og almenn borð.","night-watch.name":"Náttarvakt","night-watch.line":"Ein vaktari og ein Scrum Master halda liðunum við uppgávuna meðan tú sovir.","p-more.name":"Alt annað","p-more.line":"Smærri hugskot, sum bíða enn eftir síni tøk.","p-android.name":"Telefon og Android","p-android.line":"Kom til borðið hjá tær frá telefonini, síðani eitt upprunaligt Android-app.","p-release.name":"Alfa og longri","p-release.line":"Lukkað alfa, livandi heimasíðan, síðani beta.","p-languages.name":"Fleiri mál","p-languages.line":"Meiri enn hundrað mál, og ein niðurdýpingarháttur fyri tey, sum læra.","p-engines.name":"Fleiri AI-motorar","p-engines.line":"Vel Claude, Codex ella Gemini fyri hvønn agent.","p-pro.name":"Fakligur háttur","p-pro.line":"Vandamerki, samanrenningarbørur, hendingarkort og rekkverk.","p-self.name":"Varða um teg","p-self.line":"Móðurhættur, sjálvsrøktaráminningar og 4:20.","p-servers.name":"Ambætarar og vøkstur","p-servers.line":"Almennar ambætaraskipanir, leiklutir og ætlan fyri vøkstri.","p-livestream.name":"Streymiískoyti","p-livestream.line":"Twitch-prát, egnar emojir og eitt almennt beinleiðis sjónarhorn."},"words":{"button":"📖 Uppskipanarorð","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Leita eftir einum orði…","none":"Einki orð samsvarar.","close":"Lat aftur","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Mappan hjá verkætlanini við koduni og allari søguni av commits, vanliga eisini goymd á GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Ein sær lina av arbeiði í koduni, so at broytingar kunnu gerast uttan at nerta við høvuðsútgávuna.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Ein goymd mynd av koduni, við einum stuttum notati um, hvat broyttist. Tú kanst altíð fara aftur til eina.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"At senda goymdar myndir (commits) frá hesi teldu upp á GitHub, so at tær eru trygdarviðgjørdar og deildar."},{"id":"merge","g":"build","word":"Merge","text":"At knýta broytingarnar hjá einum branch aftur inn í høvuðsútgávuna."},{"id":"pr","g":"build","word":"Pull request","text":"At biðja um, at broytingarnar hjá einum branch verða kannaðar og knýttar inn í høvuðsútgávuna.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"At rudda koduna uttan at broyta, hvat hon ger: minni fílur, greiðari navn, minni endurtøka."},{"id":"bug","g":"build","word":"Bug","text":"Okkurt, sum ikki riggar, sum tað skal.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"At royna eitt liðugt stykki av arbeiði fyri at kanna, at tað ger tað, sum varð biðið um, áðrenn tú góðkennir tað.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"At seta eina nýggja útgávu í loftið, til dømis á ein ambætara, har fólk brúka hana."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Hugskot og arbeiði, sum ikki er ætlað enn. Einki verður gjørt við tað, fyrr enn tað fer til At gera."},{"id":"sprint","g":"team","word":"Sprint","text":"Ein stuttur tíðarbolkur av arbeiði (ofta ein ella tvær vikur) við einum avtalaðum sett av kortum at gera liðug.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Ein skjót innrokning: hvat hvør toymislimur gjørdi, hvat hann ger næst, og hvat steðgar honum.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Eitt borð við súlum (At gera, Í gerð, Liðugt), har kort flyta seg frá vinstru til høgru, sum arbeiðið gongur."},{"id":"wip","g":"team","word":"WIP-mark","text":"Work in progress: flest kort, ein súla skal hava, so at toymið ger ting liðug, áðrenn tað byrjar fleiri.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Ein AI, sum arbeiðir sjálvt við eini uppgávu: lesur koduna, ger broytingar, koyrir kanningar og boðar frá.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Eindin, sum AI-nýtsla verður tald í: umleið nøkur bókstavir av tekstið lisin ella skrivaður. Færri tokens, meira eftir av tíni ætlan.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Ein lítil skipan, sum koyrir av sær sjálvari á einum ásettum eyguablikki, t.d. tá ein AI-seta byrjar, so at toymið hoyrir tínar viðmerkingar.","also":["hooks"]}]}};
